enum NetError: Error { case offline }
func load(_ ok: Bool) -> Result<Int, NetError> {
    ok ? .success(42) : .failure(.offline)
}
print(load(true))

func twice(_ f: () throws -> Int) rethrows -> Int {
    try f() * 2
}
print(twice { 21 })

